// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        blockNum = bound(blockNum, 1, 100000);
        vm.assume(actor != address(0) && actor != address(c));

        vm.roll(blockNum);
        vm.warp(blockNum * 100 + 1);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        if (blockNum % 15 != 0) {
            // no payout block: contract must keep all its ether (10 seed + 10 sent)
            assertTrue(address(c).balance == 20 ether);
        } else {
            // payout block: contract drains to 0
            assertTrue(address(c).balance == 0);
        }
    }
}
